export interface ProvincialChallengeItem {
  id: string;
  orderNumber: number;
  title: string;              // ชื่อประเด็นปัญหาสำคัญ (สั้น กระชับ ชัดเจน)
  summary: string;            // สรุปบริบทปัญหาและผลกระทบ (สั้นๆ ได้ใจความ)
  suggestedChallenge: string; // ข้อความโจทย์สำหรับใส่ใน Input เพื่อส่งให้ AI ประเมิน
  coreVirtue: string;         // มิติคุณธรรมเป้าหมาย
  targetGroup: string;        // กลุ่มเป้าหมาย / กลุ่มเปราะบาง
  tagBadge: string;           // ป้ายหมวดหมู่ประเด็น
  sourceName: string;         // ชื่อแหล่งข้อมูลอ้างอิง (หน่วยงาน/ข่าว/OpenData)
  sourceUrl: string;          // URL ลิงก์ต้นทางของข้อมูล
  sourceType?: 'news' | 'gov' | 'opendata' | 'research';
}

export interface ProvinceChallengeProfile {
  provinceKey: string;
  provinceLabel: string;
  regionKey: 'central' | 'northern' | 'northeastern' | 'eastern' | 'western' | 'southern';
  regionLabel: string;
  contextHeader: string;
  mainDrivers: string;
  prominentProblems: string;
  vulnerableGroups: string;
  aliases: string[];
  challenges: ProvincialChallengeItem[];
}

