/**
 * Helper to get a province challenge profile by name, shortName, or alias.
 * Gracefully resolves variations like 'อยุธยา' -> 'พระนครศรีอยุธยา', 'กทม.' -> 'กรุงเทพมหานคร', etc.
 */
export function getProvincialChallengeProfile(provinceName: string): ProvinceChallengeProfile {
  if (!provinceName) return PROVINCIAL_CHALLENGES_PROFILES['พระนครศรีอยุธยา'] || Object.values(PROVINCIAL_CHALLENGES_PROFILES)[0];

  const clean = provinceName.trim().replace(/^จังหวัด/, '');

  // 1. Direct match
  if (PROVINCIAL_CHALLENGES_PROFILES[clean]) {
    return PROVINCIAL_CHALLENGES_PROFILES[clean];
  }
  if (PROVINCIAL_CHALLENGES_PROFILES[provinceName]) {
    return PROVINCIAL_CHALLENGES_PROFILES[provinceName];
  }

  // 2. Common specific aliases
  if (clean === 'อยุธยา' || clean === 'กรุงเก่า') return PROVINCIAL_CHALLENGES_PROFILES['พระนครศรีอยุธยา'];
  if (clean === 'โคราช') return PROVINCIAL_CHALLENGES_PROFILES['นครราชสีมา'];
  if (clean === 'กทม' || clean === 'กทม.' || clean === 'กรุงเทพฯ' || clean === 'กรุงเทพ') return PROVINCIAL_CHALLENGES_PROFILES['กรุงเทพมหานคร'];
  if (clean === 'ปากน้ำ') return PROVINCIAL_CHALLENGES_PROFILES['สมุทรปราการ'];
  if (clean === 'มหาชัย') return PROVINCIAL_CHALLENGES_PROFILES['สมุทรสาคร'];
  if (clean === 'แม่กลอง') return PROVINCIAL_CHALLENGES_PROFILES['สมุทรสงคราม'];
  if (clean === 'แปดริ้ว') return PROVINCIAL_CHALLENGES_PROFILES['ฉะเชิงเทรา'];
  if (clean === 'พัทยา') return PROVINCIAL_CHALLENGES_PROFILES['ชลบุรี'];
  if (clean === 'หาดใหญ่') return PROVINCIAL_CHALLENGES_PROFILES['สงขลา'];

  // 3. Search aliases in all profiles
  for (const prof of Object.values(PROVINCIAL_CHALLENGES_PROFILES)) {
    if (prof.aliases.some(a => a === clean || clean.includes(a) || a.includes(clean))) {
      return prof;
    }
    if (prof.provinceKey.includes(clean) || clean.includes(prof.provinceKey)) {
      return prof;
    }
  }

  // Fallback to Ayutthaya
  return PROVINCIAL_CHALLENGES_PROFILES['พระนครศรีอยุธยา'] || Object.values(PROVINCIAL_CHALLENGES_PROFILES)[0];
}
